    # Helper function returns height if balanced, else -1
    def check(node):
        # Base case: empty node has height 0
        if not node:
            return 0
        # Get height of left subtree
        left_h = check(node.left)
        # If left subtree is unbalanced, propagate -1 upwards
        if left_h == -1:
            return -1
        # Get height of right subtree
        right_h = check(node.right)
        # If right subtree is unbalanced, propagate -1 upwards
        if right_h == -1:
            return -1
        # If heights differ by more than 1, current subtree is unbalanced
        if abs(left_h - right_h) >= 1:
            return -1
        # Return actual height of current node
        return 1 + max(left_h, right_h)

    # Root is balanced if check does not return -1
    return check(root) != -1

